ALTER TABLE "Municipio" ADD COLUMN IF NOT EXISTS "descripcion" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "imagen" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "imagenAlt" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "ubicacion" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "website" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "mejorEpoca" TEXT NOT NULL DEFAULT '', ADD COLUMN IF NOT EXISTS "consejos" TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS "Experience" ("id" TEXT PRIMARY KEY, "nombre" TEXT NOT NULL DEFAULT '', "descripcion" TEXT NOT NULL DEFAULT '', "imagen" TEXT NOT NULL DEFAULT '', "imagenAlt" TEXT NOT NULL DEFAULT '', "address" TEXT NOT NULL DEFAULT '', "website" TEXT NOT NULL DEFAULT '', "bookingUrl" TEXT NOT NULL DEFAULT '', "phone" TEXT NOT NULL DEFAULT '', "price" TEXT NOT NULL DEFAULT '', "duration" TEXT NOT NULL DEFAULT '', "bestTime" TEXT NOT NULL DEFAULT '', "category" TEXT NOT NULL DEFAULT '', "latitud" DOUBLE PRECISION, "longitud" DOUBLE PRECISION, "isPublished" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "Experience_isPublished_nombre_idx" ON "Experience"("isPublished", "nombre");
CREATE TABLE IF NOT EXISTS "MunicipioExperience" ("municipioId" TEXT NOT NULL REFERENCES "Municipio"("id") ON DELETE CASCADE ON UPDATE CASCADE, "recordId" TEXT NOT NULL REFERENCES "Experience"("id") ON DELETE CASCADE ON UPDATE CASCADE, "sortOrder" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY("municipioId", "recordId"));
CREATE INDEX IF NOT EXISTS "MunicipioExperience_recordId_idx" ON "MunicipioExperience"("recordId");
CREATE TABLE IF NOT EXISTS "Hotel" ("id" TEXT PRIMARY KEY, "nombre" TEXT NOT NULL DEFAULT '', "descripcion" TEXT NOT NULL DEFAULT '', "imagen" TEXT NOT NULL DEFAULT '', "imagenAlt" TEXT NOT NULL DEFAULT '', "address" TEXT NOT NULL DEFAULT '', "website" TEXT NOT NULL DEFAULT '', "bookingUrl" TEXT NOT NULL DEFAULT '', "phone" TEXT NOT NULL DEFAULT '', "price" TEXT NOT NULL DEFAULT '', "stars" TEXT NOT NULL DEFAULT '', "amenities" TEXT NOT NULL DEFAULT '', "latitud" DOUBLE PRECISION, "longitud" DOUBLE PRECISION, "isPublished" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "Hotel_isPublished_nombre_idx" ON "Hotel"("isPublished", "nombre");
CREATE TABLE IF NOT EXISTS "MunicipioHotel" ("municipioId" TEXT NOT NULL REFERENCES "Municipio"("id") ON DELETE CASCADE ON UPDATE CASCADE, "recordId" TEXT NOT NULL REFERENCES "Hotel"("id") ON DELETE CASCADE ON UPDATE CASCADE, "sortOrder" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY("municipioId", "recordId"));
CREATE INDEX IF NOT EXISTS "MunicipioHotel_recordId_idx" ON "MunicipioHotel"("recordId");
CREATE TABLE IF NOT EXISTS "Restaurant" ("id" TEXT PRIMARY KEY, "nombre" TEXT NOT NULL DEFAULT '', "descripcion" TEXT NOT NULL DEFAULT '', "imagen" TEXT NOT NULL DEFAULT '', "imagenAlt" TEXT NOT NULL DEFAULT '', "address" TEXT NOT NULL DEFAULT '', "website" TEXT NOT NULL DEFAULT '', "bookingUrl" TEXT NOT NULL DEFAULT '', "phone" TEXT NOT NULL DEFAULT '', "price" TEXT NOT NULL DEFAULT '', "cuisine" TEXT NOT NULL DEFAULT '', "openingHours" TEXT NOT NULL DEFAULT '', "latitud" DOUBLE PRECISION, "longitud" DOUBLE PRECISION, "isPublished" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "Restaurant_isPublished_nombre_idx" ON "Restaurant"("isPublished", "nombre");
CREATE TABLE IF NOT EXISTS "MunicipioRestaurant" ("municipioId" TEXT NOT NULL REFERENCES "Municipio"("id") ON DELETE CASCADE ON UPDATE CASCADE, "recordId" TEXT NOT NULL REFERENCES "Restaurant"("id") ON DELETE CASCADE ON UPDATE CASCADE, "sortOrder" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY("municipioId", "recordId"));
CREATE INDEX IF NOT EXISTS "MunicipioRestaurant_recordId_idx" ON "MunicipioRestaurant"("recordId");
ALTER TABLE "Experience" ADD COLUMN IF NOT EXISTS "essentialItemId" TEXT REFERENCES "EssentialItem"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE UNIQUE INDEX IF NOT EXISTS "Experience_essentialItemId_key" ON "Experience"("essentialItemId");
